## solutions

#### iterative

```cpp
Node* insertNode(Node* head, std::string value, int idx) {
  if (idx == 0) {
    Node* createdNode = new Node(value);
    createdNode->next = head;
    return createdNode;
  }

  Node* current = head;
  int count = 0;
  while (current != nullptr) {
    if (count == idx - 1) {
      Node* createdNode = new Node(value);
      Node* next = current->next;
      current->next = createdNode;
      createdNode->next = next;
    }

    count += 1;
    current = current->next;
  }
  return head;
}
```

- n = number of nodes
- Time: O(n)
- Space: O(1)

#### recursive

```cpp
Node* insertNode(Node* head, std::string value, int idx) {
  if (idx == 0) {
    Node* createdNode = new Node(value);
    createdNode->next = head;
    return createdNode;
  }

  if (head == nullptr) {
    return nullptr;
  }

  if (idx == 1) {
    Node* createdNode = new Node(value);
    Node* next = head->next;
    head->next = createdNode;
    createdNode->next = next;
  } else {
    insertNode(head->next, value, idx - 1);
  }

  return head;
}
```

- n = number of nodes
- Time: O(n)
- Space: O(n)
